import {
  billingHttpError,
  limitBillingRequest,
  billingSessionUser,
  privateBillingHeaders,
} from "@/lib/billing/http";
import { readBillingStatus } from "@/lib/billing/status";

export const runtime = "nodejs";
export async function GET() {
  try {
    const userId = await billingSessionUser();
    await limitBillingRequest(userId, "status");
    return Response.json(await readBillingStatus(userId), {
      headers: privateBillingHeaders,
    });
  } catch (error) {
    return billingHttpError(error);
  }
}
